Given two arrays a[] and b[], find their intersection — the unique elements that appear in both. Ignore duplicates, and the result can be in any order.Input: a[] = [1, 2, 1, 3, 1], b[] = [3, 1, 3, 4, 1]Output: [1, 3]Explanation: 1 and 3 are the only common elements and we need to print only one occurrence of common elementsInput: a[] = [1, 1, 1], b[] = [1, 1, 1, 1, 1]Output: [1]Explanation: 1 is the only common element present in both the arrays.Input: a[] = [1, 2, 3], b[] = [4, 5, 6]Output: []Explanation: No common element in both the arrays.Try It YourselfTable of Content[Naive Approach] Using Triple Nested Loops - O(n × n × m) Time and O(1) Space[Better Approach] Using Nested Loops and Hash Set - O(n × m) Time and O(n) Space[Expected Approach 1] Using Two Hash Sets - O(n+m) Time and O(n) Space[Expected Approach 2] Using One Hash Set - O(n+m) Time and O(n) Space[Naive Approach] Using Triple Nested Loops - O(n × n × m) Time and O(1) SpaceThe idea is to find all unique elements that appear in both arrays by checking each element of one array against the other and ensuring no duplicates are added to the result.Step By Step Implementation:Initialize an empty array for result.Traverse through a[] and for every element check if it is in b[], then check if it is already in result or not. If in b[] and not in result, then add it to the result.Return result.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> intersect(vector<int>& a, vector<int>& b) {
    vector<int> res;

    // Traverse through a[] and search every element
    // a[i] in b[]
    for (int i = 0; i < a.size(); i++) {    
        for (int j = 0; j < b.size(); j++) {

            // If found, check if the element is already 
            // in the result to avoid duplicates
            if (a[i] == b[j]) { 
                int k;
                for (k = 0; k < res.size(); k++) 
                    if (res[k] == a[i]) 
                        break;
                if (k == res.size()) {
                    res.push_back(a[i]);
                }
            }
        }
    }

    return res;
}

int main() {
    vector<int> a = {1, 2, 3, 2, 1};
    vector<int> b = {3, 2, 2, 3, 3, 2};

    vector<int> res = intersect(a, b);

    for (int i = 0; i < res.size(); i++) 
        cout << res[i] << " ";

    return 0;
}


